#!/bin/bash
# Builds the Android app and sends it to your testers with Firebase App Distribution.
#
# Usage (from the project folder):
#   ./scripts/release_android.sh "What changed in this version"
#
# One-time setup: see README → "Sending Android updates".
set -e
cd "$(dirname "$0")/.."

NOTES="${1:-New version}"
GROUP="${TESTER_GROUP:-testers}"

# Firebase Android app ID, read from the file generated by `flutterfire configure`.
APP_ID=$(grep -A8 "static const FirebaseOptions android" lib/firebase_options.dart \
  | grep "appId" | head -1 | sed -E "s/.*appId: *'([^']+)'.*/\1/")
if [ -z "$APP_ID" ]; then
  echo "Could not find the Android appId in lib/firebase_options.dart. Run: flutterfire configure"
  exit 1
fi

# A build number that always goes up, so phones accept it as an update.
BUILD_NUMBER=$(( $(date +%s) / 60 ))

echo "▶ Building APK (build $BUILD_NUMBER)…"
flutter build apk --release --split-per-abi --build-number="$BUILD_NUMBER"

APK="build/app/outputs/flutter-apk/app-arm64-v8a-release.apk"
echo "▶ Uploading $APK to Firebase App Distribution (group: $GROUP)…"
firebase appdistribution:distribute "$APK" \
  --app "$APP_ID" \
  --groups "$GROUP" \
  --release-notes "$NOTES"

echo "✓ Done. Testers in '$GROUP' will get a notification to update."
